//! These tests validate lineage DATA and refusal boundaries. They deliberately
//! do not turn the unfinished recipient/F2 path into native execution authority.
use super::*;
use crate::pet_runtime::{planning::Catalog,store::nonce,admission::{Review,Payment},admission_tests::{Fixture,evidence,budget}};
use crate::pet_memory::{Owner,Scope,context_model::{GoalGrant,GoalConsent,GOAL_INPUT_LIMIT}};
fn snapshot()->(crate::pet_runtime::admission_tests::Fixture,crate::pet_runtime::authority::Authority,crate::pet_runtime::model::Record,crate::pet_runtime::lease_controller::Pending,crate::pet_runtime::lease_controller::Owned,crate::chat::Chat,AdmissionSpec,Published){
 let(f,a,g,p,o,main)=crate::pet_runtime::generated_effect_tests::setup(true);let mut spec=g.admissions[0].spec.clone();let policy=spec.planning_policy.as_mut().unwrap();policy.catalog=Catalog::PeerCorrespondenceMemoryV1;policy.limits.max_rounds=1;policy.limits.no_progress_limit=1;spec.budget.max_model_calls=1;spec.context.schema_version=2;spec.context.memory=Some(crate::pet_memory::context_model::Selection{schema_version:1,references:vec![Reference{id:"private-memory-note".into(),revision:7,owner:Owner{pet_id:spec.owner.pet_id.clone(),scope:Scope::Pet{}},content_hash:"a".repeat(64),expires_at:None}]});spec.context_hash=model::fingerprint(&spec.context).unwrap();spec.memory_data=Some(GoalGrant{calendar_selection:None,schema_version:1,received_request:None,consent:GoalConsent::BoundedGoalContext,destination:Destination::Server{provider:"ollama".into(),endpoint:"http://127.0.0.1:11444/v1/chat/completions".into(),model:spec.resolved_model.clone()},max_input_bytes:GOAL_INPUT_LIMIT});assert!(spec.binding_format());let source=Snapshot::from_spec(&spec).unwrap().unwrap();let mut reference=g.generated_plans[0].clone();reference.source.main_spec_hash=model::fingerprint(&spec).unwrap();reference.source.policy_hash=model::fingerprint(&spec.planning_policy).unwrap();let published=Published{round_data:None,schema_version:1,source,generated_plan:reference};assert!(published.valid());(f,a,g,p,o,main,spec,published)
}
#[test]fn lineage_keeps_all_exact_revisions_and_cannot_substitute_another_pet_or_model(){
 let(_f,_a,_g,_p,_o,_main,spec,p)=snapshot();assert!(p.for_spec(&spec));let mut wrong=p.clone();wrong.source.references[0].revision+=1;assert!(!wrong.for_spec(&spec));let mut wrong=p.clone();wrong.source.references.clear();assert!(!wrong.valid());let mut wrong=p.clone();wrong.source.references[0].owner.pet_id="ai_lmstudio".into();assert!(!wrong.valid());let mut wrong=p.clone();wrong.source.admission_hash="b".repeat(64);assert!(!wrong.valid());let mut wrong=p.clone();wrong.source.destination=Destination::Server{provider:"ollama".into(),endpoint:"https://example.invalid/v1/chat/completions".into(),model:"fixture-free".into()};assert!(!wrong.valid());let mut wrong=p.clone();if let Destination::Server{model,..}=&mut wrong.source.destination{*model="other-model".into();}assert!(!wrong.for_spec(&spec));
}
#[test]fn model_projection_excludes_raw_records_private_memory_identity_and_native_controls(){
 let(_f,_a,_g,_p,_o,_main,_spec,p)=snapshot();let data=p.model_metadata();let encoded=data.to_string();assert_eq!(data["sourceMemoryCount"],1);assert_eq!(data["sourceModelConsentTransfers"],false);for secret in ["private-memory-note",p.generated_plan.source.lease_id.as_str(),p.generated_plan.source.controller_id.as_str(),p.source.conversation_id.as_str(),"127.0.0.1"]{assert!(!encoded.contains(secret),"unexpected source metadata: {secret}");}let mut value=serde_json::to_value(&p).unwrap();value["source"]["grantAllMemory"]=serde_json::json!(true);assert!(serde_json::from_value::<Published>(value).is_err());
}
#[test]fn published_lineage_data_alone_cannot_create_a_canonical_received_source(){
 let(_f,a,_g,_p,_o,_main,_spec,p)=snapshot();let fake=crate::pet_runtime::messages::ReceivedReference{decision_id:p.generated_plan.decision_id.clone(),message_id:nonce().unwrap(),scope_hash:"a".repeat(64)};assert!(a.received_planned_data_unlocked(&fake,"ai_lmstudio",crate::assistant_memory::now()).is_err());
}
#[test]fn memory_catalogue_requires_real_selected_context_and_its_own_native_data_consent(){
 let f=Fixture::new();let g=f.goal("ollama");let at=crate::assistant_memory::now();let mut b=budget();b.deadline_at=at+60_000;b.max_model_calls=1;b.max_tool_calls=2;b.max_output_bytes=64_000;b.payment=Payment::LocalOnly;let review=Review::prepare_planning_catalog(&g,evidence(&g,at),b,crate::pet_runtime::planning::Limits{max_rounds:1,max_steps:2,max_output_bytes:2048,no_progress_limit:1},&crate::pet_config::defaults(),Catalog::PeerCorrespondenceMemoryV1,"blocked-memory-catalogue".into(),nonce().unwrap(),at);assert!(matches!(review,Err(crate::pet_runtime::admission::Denial::Unsupported)));assert!(g.admissions.is_empty());assert!(!f.path.join("authority").exists());
}
#[test]fn iterative_memory_lineage_retains_exact_original_revisions_and_never_promotes_legacy_data(){
 let(_f,_a,_g,_p,_o,_main,mut spec,legacy)=snapshot();let legacy_bytes=serde_json::to_vec(&legacy).unwrap();
 spec.schema_version=24;spec.budget.max_model_calls=4;let policy=spec.planning_policy.as_mut().unwrap();policy.catalog=Catalog::PeerDelegationIterationV1;policy.schema_version=3;policy.limits.max_rounds=2;policy.limits.no_progress_limit=2;
 assert!(spec.binding_format());assert!(!legacy.for_spec(&spec));
 let mut plan=legacy.generated_plan.clone();plan.source.main_spec_hash=model::fingerprint(&spec).unwrap();plan.source.policy_hash=model::fingerprint(&spec.planning_policy).unwrap();
 let published=Published::from_memory(&spec,plan).unwrap();assert_eq!(published.schema_version,3);assert_eq!(published.source.schema_version,3);assert!(published.for_spec(&spec));assert_eq!(published.source.references,legacy.source.references);assert!(published.round_data.is_none());
 let mut changed=published.clone();changed.source.references[0].revision+=1;assert!(!changed.for_spec(&spec));let mut changed=published.clone();changed.source.references.clear();assert!(!changed.valid());let mut changed=published.clone();changed.generated_plan.round_index=2;assert!(!changed.valid());let mut changed=published.clone();changed.source.schema_version=2;assert!(!changed.valid());
 let projection=published.model_metadata().to_string();for secret in ["private-memory-note",published.source.conversation_id.as_str(),published.generated_plan.source.lease_id.as_str(),"127.0.0.1"]{assert!(!projection.contains(secret));}
 assert_eq!(serde_json::to_vec(&legacy).unwrap(),legacy_bytes);assert_eq!(legacy.schema_version,1);
}
